// === Tab: Sechskant ===
class Sechskant {
	constructor(x, y, rx, ry, h) {
		this.x = x;
		this.y = y;
		this.rx = rx; 
		this.ry = ry;
		this.h = h;
		this.angle = 0;
		this.speed = random(-0.1, 0.1);
	}

	show(debug = false) {
		push();
		noFill();
		stroke(64, 64);
		if (debug) {
			ellipse(this.x, this.y, this.rx*2, this.ry*2);
			ellipse(this.x, this.y - this.h/2, this.rx*2, this.ry*2);
			ellipse(this.x, this.y + this.h/2, this.rx*2, this.ry*2);
		}
		this.shape(this.x, this.y, this.h, this.rx, this.ry);
		pop();

		this.angle += this.speed;
	}

	shape(cx, cy, h, rx, ry) {
		const num = 6;
		let startAngle = this.angle;
		let pts = [];
		let stIdx = 0, stX = -Infinity;
		for (let i = 0; i < num; i++) {
			const angle = i/num*TAU + startAngle;
			const x = cx + cos(angle) * rx;
			const y = cy + sin(angle) * ry + h/2;
			pts.push({x, y});
			if (x > stX) {
				stX = x;
				stIdx = i;
			}
		}
		// shift, so pts[0] ist the most right one (highest x)
		for (let i = 0; i < stIdx; i++) {
			pts.push(pts.shift());
		}
		// circle(pts[0].x, pts[0].y, 5)

		var angle = (this.angle + 10000* TAU - TAU/12) % (TAU/6);
		const chrs = '-+o+oO*O#';
		// const chIdx = constrain(Math.round(sin(angle*3) * chrs.length/3), 0, ~~(chrs.length/3-1));
		const chIdx = constrain(Math.round((angle/(TAU/6)) * chrs.length/3), 0, ~~(chrs.length/3-1));		

		// 4 faces:
		// 1) most right
		page.fill(chrs[chIdx], [pts[0], pts[1], {x: pts[1].x, y: pts[1].y-h}, {x: pts[0].x, y: pts[0].y-h}]); // 'O'
		// 2) center
		page.fill(chrs[(chIdx+~~(chrs.length/3))%chrs.length], [pts[1], pts[2], {x: pts[2].x, y: pts[2].y-h}, {x: pts[1].x, y: pts[1].y-h}]); // '-'
		// 3) most left
		page.fill(chrs[(chIdx+~~(chrs.length*2/3))%chrs.length], [pts[2], pts[3], {x: pts[3].x, y: pts[3].y-h}, {x: pts[2].x, y: pts[2].y-h}]); // '#'
		// 4) top face
		page.fill('+', [{x: pts[0].x, y: pts[0].y-h}, {x: pts[1].x, y: pts[1].y-h}, {x: pts[2].x, y: pts[2].y-h}, {x: pts[3].x, y: pts[3].y-h}, {x: pts[4].x, y: pts[4].y-h}, {x: pts[5].x, y: pts[5].y-h}]);
	} // shape()

} // Sechskant

// === Tab: Page ===
class Page {
	constructor(nx, ny, mar, ts) {
		this.nx = nx;		
		this.ny = ny;
		this.mar = mar;
		this.ts = ts;
		this.init();
	}

	init() {
		this.page = [];
		for (let y = 0; y < ny; y++) {
			this.page[y] = [];
			for (let x = 0; x < nx; x++) {
				this.page[y][x] = ' '; // random(['.','8','Z','O']);
			}
		}
	} // init()

	show() {
		// return
		push();
		textSize(this.ts);
		textAlign(CENTER, CENTER);
		textFont('let New');
		textStyle(BOLD);
		noStroke();
		fill(4, 4, 12, 212);
		for (let y = 0; y < this.ny; y++) {
			for (let x = 0; x < this.nx; x++) {
				text(this.page[y][x], this.mar + (x+0.5)*this.ts, this.mar + (y+0.5)*this.ts);
			}
		}
		pop();
	} // show()

	fill(ch, polygon) {
		for (let y = 0; y < this.ny; y++) {
			for (let x = 0; x < this.nx; x++) {
				const xx = this.mar + (x+0.5)*this.ts;
				const yy = this.mar + (y+0.5)*this.ts;
				if (this.isPointInPolygon(xx, yy, polygon)) {
					this.page[y][x] = ch;
				}
			}
		}
		// console.log(polygon);
	} // fill()

	// if a point is inside a polygon (ray-casting algorithm)
	isPointInPolygon(x, y, polygon) {
		const epsilon = 1e-6;
		let inside = false;

		for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
			let xi = polygon[i].x, yi = polygon[i].y;
			let xj = polygon[j].x, yj = polygon[j].y;

			let intersect = ((yi > y + epsilon) !== (yj > y + epsilon)) &&
				(x < (xj - xi) * (y - yi) / (yj - yi + epsilon) + xi);

			if (intersect) inside = !inside;
		}

		return inside;
	} // isPointInPolygon

} // Page

